mapper.select:

WHERE true

    AND c.pk_comu_id_comuna = #{comuna}


    AND j.pk_caju_id_calidad_juridica = #{calidadJuridica}


    AND UPPER(s.sost_nombre) LIKE UPPER(#{nombre})


    AND UPPER(s.sost_rut) LIKE UPPER(#{rut})


    ORDER BY #{orderBy} #{order}


    LIMIT #{limit} OFFSET #{offset}

SELECT count(s.pk_sost_id_sostenedor) as result
    FROM sostenedor s
    LEFT JOIN comuna c ON c.pk_comu_id_comuna = s.fk_sost_id_comuna
    LEFT JOIN calidad_juridica j on j.pk_caju_id_calidad_juridica = s.fk_sost_id_calidad_juridica
WHERE true

    AND c.pk_comu_id_comuna = #{comuna}


    AND j.pk_caju_id_calidad_juridica = #{calidadJuridica}


    AND UPPER(s.sost_nombre) LIKE UPPER(#{nombre})


    AND UPPER(s.sost_rut) LIKE UPPER(#{rut})


    ORDER BY #{orderBy} #{order}

SELECT CASE WHEN COUNT(fk_uned_id_sostenedor) > 0 THEN 1 ELSE 0 END AS result
FROM unidad_educativa
WHERE fk_uned_id_sostenedor = #{id}
